INSERT IGNORE INTO `base_i18n` (`target_type`, `target_id`, `locale`, `name`) VALUES (1, 1230, 'ja-JP', '<h2>プライバシーポリシー</h2><p>このアプリをご利用いただきありがとうございます。当社はお客様の個人情報を大切にして保護し、アカウントへのログイン、アプリケーション機能、および顧客サービスを提供するために必要な範囲内でのみ関連情報を処理します。 </p><h3> 1. 情報の利用について </h3><p> 当社は、お客様の情報を法令および本規約に従って利用し、それと関係のない目的には利用いたしません。 </p><h3> 2. お客様の権利 </h3><p> お客様は、法律に従って個人情報を照会、修正、削除するか、アプリケーションで公開されているチャネルを通じて当社に連絡することができます。 </p>');
INSERT IGNORE INTO `base_i18n` (`target_type`, `target_id`, `locale`, `name`) VALUES (1, 1240, 'ja-JP', '<h2>利用規約</h2><p>このアプリケーションへようこそ。本アプリケーションをご利用になる前に、本規約をよくお読みいただき、ご理解いただいた上でご利用ください。アプリケーション サービスの使用を開始すると、本契約および関連規則に従うことに同意したものとみなされます。 </p><h3> 1.サービスのご利用について </h3><p> 各種機能は法令・コンプライアンスを遵守し、ページの指示に従ってご利用ください。このアプリケーションを使用して、違法または他人の権利や利益を損なう活動に従事することはできません。 </p><h3> 2. 本規約の変更 </h3><p> 当社は、ビジネスおよび法令の変更に応じて本規約を更新し、更新された内容をアプリケーション内で表示します。 </p>');
